def is_palindrome(s):
    t = [c.lower() for c in s if c.isalnum()]
    return t == t[::-1]

def run_length_encode(s):
    out, i = [], 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))
        i = j
    return ''.join(out)

def caesar_shift(s, k):
    r = []
    for c in s:
        if c.islower(): r.append(chr((ord(c)-97+k)%26+97))
        elif c.isupper(): r.append(chr((ord(c)-65+k)%26+65))
        else: r.append(c)
    return ''.join(r)

def second_largest(nums):
    u = sorted(set(nums))
    return u[-2] if len(u) >= 2 else None

def dedupe(items):
    seen, out = set(), []
    for x in items:
        if x not in seen:
            seen.add(x); out.append(x)
    return out
